<!DOCTYPE html>
<html lang="zh-CN">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>月薪 3000 这样存</title>
<style>
  * {
    box-sizing: border-box;
  }
  body {
    margin: 0;
    padding: 40px 20px;
    background-color: #e9e9e9;
    display: flex;
    justify-content: center;
    font-family: 'Kaiti', '楷体', 'STKaiti', serif;
  }
  .notebook-page {
    width: 800px;
    background-color: #fff;
    background-image: repeating-linear-gradient(transparent 0px, transparent 39px, #ccc 39px, #ccc 40px);
    background-size: 100% 40px;
    background-position: 0 20px;
    padding-top: 20px;
    padding-bottom: 60px;
    box-shadow: 0 4px 20px rgba(0,0,0,0.15);
    border-radius: 4px;
    position: relative;
    color: #8b2525;
    font-size: 22px;
  }
  .notebook-page::before {
    content: '';
    position: absolute;
    top: 0;
    left: 15px;
    bottom: 0;
    width: 20px;
    background-image: radial-gradient(circle at 10px 20px, #e9e9e9 6px, transparent 7px);
    background-size: 20px 40px;
    background-position: 0 20px;
    border-right: 1px solid #ddd;
    z-index: 1;
  }
  .grid-row {
    height: 40px;
    display: flex;
    align-items: flex-end;
    padding-bottom: 6px;
    position: relative;
    z-index: 2;
  }
  .grid-row.h-2 {
    height: 80px;
    align-items: flex-start;
    padding-bottom: 0;
  }
  .date-row {
    justify-content: flex-end;
    padding-right: 60px;
    border-bottom: 1px solid #888;
    font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
    color: #555;
    font-size: 16px;
  }
  .title-row {
    justify-content: center;
    align-items: center;
    padding-left: 35px;
  }
  .title-row h1 {
    font-size: 52px;
    font-weight: normal;
    color: #222;
    margin: 0;
    letter-spacing: 6px;
  }
  .indent-1 {
    padding-left: 100px;
  }
  .indent-2 {
    padding-left: 160px;
  }
  .col-year {
    width: 160px;
    padding-left: 60px;
    height: 40px;
    display: flex;
    align-items: flex-end;
    padding-bottom: 6px;
  }
  .col-action {
    width: 180px;
    height: 40px;
    display: flex;
    align-items: flex-end;
    padding-bottom: 6px;
  }
  .col-amounts {
    display: flex;
    gap: 30px;
  }
  .amount-item {
    display: flex;
    flex-direction: column;
    align-items: center;
  }
  .amount-item .h-1, .brace-left .h-1 {
    height: 40px;
    display: flex;
    align-items: flex-end;
    padding-bottom: 6px;
  }
  .brace-left {
    display: flex;
    flex-direction: column;
  }
  .brace-symbol {
    margin: 0 10px;
    display: flex;
    align-items: center;
    height: 80px;
  }
  .brace-right {
    height: 80px;
    display: flex;
    align-items: center;
  }
  .result-label {
    width: 160px;
    display: inline-block;
  }
  .result-val-lg {
    width: 140px;
    display: inline-block;
  }
  .result-val-md {
    width: 120px;
    display: inline-block;
  }
</style>
</head>
<body>

<div class="notebook-page">
  <!-- Line 1 -->
  <div class="grid-row date-row">
    <span>Date.</span>
  </div>

