  <div class="grid-row h-2 title-row">
    <h1>月薪 3000 这样存</h1>
  </div>

  <!-- Line 4 -->
  <div class="grid-row"></div>

  <!-- Line 5 -->
  <div class="grid-row indent-1">
    收入3000，每月存1000元
  </div>

  <!-- Line 6 -->
  <div class="grid-row"></div>

  <!-- Line 7 & 8 -->
  <div class="grid-row h-2">
    <div class="col-year">第1年：</div>
    <div class="col-action">1000分成3份</div>
    <div class="col-amounts">
      <div class="amount-item">
        <div class="h-1">300元</div>
        <div class="h-1">一年期</div>
      </div>
      <div class="amount-item">
        <div class="h-1">300元</div>
        <div class="h-1">两年期</div>
      </div>
      <div class="amount-item">
        <div class="h-1">400元</div>
        <div class="h-1">三年期</div>
      </div>
