    <div class="col-year">第4年：</div>
    <div class="brace-left">
      <div class="h-1">每月有一笔400元到期</div>
      <div class="h-1">每月继续存1000元</div>
    </div>
    <div class="brace-symbol">
      <svg width="20" height="70" viewBox="0 0 20 70" fill="none" stroke="#8b2525" stroke-width="1.5">
        <path d="M 18 5 C 8 5, 8 30, 2 35 C 8 40, 8 65, 18 65" />
      </svg>
    </div>
    <div class="brace-right">共1400元存3年期</div>
  </div>

  <!-- Line 21 -->
  <div class="grid-row indent-2">
    <span class="result-label">12个月后得到</span>
    <span class="result-val-lg">24个1300元</span>
    <span>12个1400元</span>
  </div>

  <!-- Bottom Padding Lines -->
  <div class="grid-row"></div>
  <div class="grid-row"></div>
</div>

</body>
</html>
